use verus::prelude::*;

verus! {

    /// Returns the maximum element of a non-empty vector of `usize`.
    /// Requires:
    ///     lst.len() > 0
    /// Ensures:
    ///     There is some valid index `i` such that `lst[i] == result`, and
    ///     for every index `j` in the vector, `lst[j] <= result`.
    pub fn max_of_list(lst: &Vec<usize>) -> (result: usize)
        requires
            lst.len() > 0,
        ensures
            // result is exactly an element of the list
            exists |i: usize| i < lst.len() && lst.index(i) == result,
            // result is at least as large as every element
            forall |j: usize| j < lst.len() ==> lst.index(j) <= result,
    {
        let n = lst.len();

        // Initialize: we know n >= 1
        let mut i: usize = 1;
        let mut current_max: usize = lst.index(0);

        // Loop over the remaining elements
        while i < n
            invariant
                // i never exceeds n
                i <= n,
                // current_max is the max of lst[0..i)
                exists |k: usize| k < i && lst.index(k) == current_max,
                forall |j: usize| j < i ==> lst.index(j) <= current_max,
            decreases n - i
        {
            let x = lst.index(i);
            if x > current_max {
                current_max = x;
            }
            i += 1;
        }

        current_max
    }
}